param([Parameter(Mandatory=$true)][ValidateSet('DebugCPU','ReleaseCPU','Debug','Release')][string]$Configuration,[switch]$ExecutionAuthorized)
# One actual bounded component process only; never Run/solver/help/build/reader/next stage.
$ErrorActionPreference='Stop';if(!$ExecutionAuthorized){throw 'Root full review and explicit component execution authorization required'}
$Configuration=@('DebugCPU','ReleaseCPU','Debug','Release')|Where-Object{$_ -ieq $Configuration};$gpu=$Configuration -in @('Debug','Release');$backend=if($gpu){'GPU'}else{'CPU'};$mem=$Configuration -ceq 'Debug';$count=if($gpu){110}else{85}
$tests=Split-Path -Parent $PSScriptRoot;$repo=(Get-Item -LiteralPath $tests).Parent.Parent.Parent.Parent.FullName;$src=Join-Path $repo 'src';$logs=Join-Path $tests 'logs';$tag='upl_damp_component_'+$Configuration+'_run_r1'
$folder=Join-Path $tests ('outputs\'+$tag);$record=Join-Path $logs ($tag+'.run.json');$callPath=Join-Path $logs ($tag+'.call.json');$logPath=Join-Path $logs ($tag+'.log')
function E([string]$p){$f=Get-Item -LiteralPath $p -Force;[ordered]@{path=$f.FullName;bytes=[long]$f.Length;sha256=(Get-FileHash -LiteralPath $p -Algorithm SHA256).Hash.ToLowerInvariant()}}
function J([string]$p){[IO.File]::ReadAllText($p)|ConvertFrom-Json}
function Need([bool]$ok,[string]$why){if(!$ok){throw $why}}
function V($rows){foreach($e in $rows){Need ($e.path -and $null -ne $e.bytes -and $e.sha256) 'Missing bound Entry';$a=E $e.path;Need ($a.bytes -eq $e.bytes -and $a.sha256 -ieq $e.sha256) ('Changed artifact: '+$e.path)}}
function Fresh($paths){foreach($p in $paths){Need (!(Test-Path -LiteralPath $p)) ('Retained path protected: '+$p)}}
function Save([string]$p,$v){Fresh @($p);[IO.File]::WriteAllText($p,($v|ConvertTo-Json -Depth 18)+[Environment]::NewLine,(New-Object Text.UTF8Encoding($false)))}
Fresh @($folder,$record,$callPath,$logPath);$helperE=E (Join-Path $logs ('upl_damp_component_'+$Configuration+'_r1.helper.json'));$h=J $helperE.path;$buildE=$h.source_build;$b=J $buildE.path
Need ($h.passed -and $h.stage -ceq 'upl_damp_component_build_r1' -and $h.kind -ceq 'component' -and $h.backend -ceq $backend -and $h.configuration -ceq $Configuration -and $h.exact_link_closure_verified -and $h.build_and_source_bindings_unchanged -and @($h.objects).Count -eq $count -and $h.link_object_count -eq ($count+1) -and @($h.runtime).Count -eq 4 -and !$h.program_run -and !$h.solver_started) 'Own passed current component helper required'
Need ($b.passed -and $b.stage -ceq 'upl_damp_build_r2' -and $b.configuration -ceq $Configuration -and $b.source_bindings_unchanged -and $b.canonical_programs_unchanged -and $b.runtime_unchanged -and @($b.source_snapshot).Count -eq 265 -and @($h.source_snapshot).Count -eq 265 -and @($h.canonical_programs_before).Count -eq 7 -and @($h.canonical_runtime_before).Count -eq 4) 'Own current r2 source265/doc/runtime/canonical closure required'
$manifestE=E (Join-Path $logs 'upl_damp_r1.inputs.json');$m=J $manifestE.path;$jobs=@($m.jobs|Where-Object{$_.window -ceq 'smoke'});Need ($m.passed -and $m.prepared -and $m.stage -ceq 'upl_damp_prepare_r1' -and $jobs.Count -eq 1) 'Own prepared positive smoke input required';$job=$jobs[0]
Need ($job.damping -eq 1 -and $job.damping_coef -eq 0.02 -and $job.inverse_DOM_exact -and $job.physics_changed_only_in_declared_damping_nodes -and $job.dt_s -eq [Math]::Pow(2,-19) -and $job.steps -eq 2 -and $job.expected_samples -eq 3) 'Positive dyadic candidate input only'
$bindings=@((E $PSCommandPath),(E (Join-Path $tests 'notes\upl_damp_plan_r1.json')),(E (Join-Path $tests 'notes\upl_damp_components_r1.json')),$helperE,$buildE,$h.program,$h.helper_object,$h.compile_call,$h.link_call,$manifestE,$job.configuration,$job.runtime,$job.initial_BI4,$job.normals)+@($h.inputs)+@($h.objects)+@($h.tools)+@($h.libraries)+@($h.author_files)+@($h.canonical_programs_before)+@($h.canonical_runtime_before)+@($m.inputs)
foreach($p in @($h.source_snapshot)+@($h.documentation_snapshot,$h.case_readme_snapshot)){Need ($p.original.bytes -eq $p.snapshot.bytes -and $p.original.sha256 -ieq $p.snapshot.sha256) 'Current source/documentation pair differs';$bindings+=@($p.original,$p.snapshot)};foreach($p in $h.runtime){$bindings+=@($p.original,$p.copy)}
$prior=$null;if($Configuration -in @('ReleaseCPU','Release')){$prior=E (Join-Path $logs ('upl_damp_'+$backend+'_smoke_r1.native.json'));$p=J $prior.path;Need ($p.passed -and $p.stage -ceq 'upl_damp_native_r1' -and $p.backend -ceq $backend -and $p.window -ceq 'smoke' -and $p.original_native_guards_passed -and $p.bindings_unchanged) 'Own backend Debug smoke native must pass before Release component';$q=J $p.completion.path;Need ($q.passed -and $q.samples -eq 3 -and $q.backend -ceq ($backend+'_public')) 'Own Debug smoke completion differs';$bindings+=@($prior,$p.source_run,$p.reader_call,$p.completion)+@($p.inputs)+@($p.files)}
$targetArgs=@('--input',$job.runtime.path,'--out',$folder);$tool=$h.program;$argv=$targetArgs
if($mem){$tool=E 'C:\Program Files\NVIDIA GPU Computing Toolkit\CUDA\v11.7\compute-sanitizer\compute-sanitizer.exe';Need ($tool.sha256 -ceq 'db5aaaf6fa07566eb10b71f5864e2229d8f061950618bb1270a56a25acd17589') 'Reviewed CUDA11.7 memcheck tool differs';$bindings+=@($tool);$argv=@('--tool','memcheck','--leak-check','full','--error-exitcode','99',$h.program.path)+$targetArgs}
V $bindings;[IO.File]::WriteAllBytes($logPath,[byte[]]@());$started=[DateTime]::UtcNow.ToString('o');$code=$null;$failure=$null;$saved=$ErrorActionPreference;Push-Location $src
try{$ErrorActionPreference='Continue';$global:LASTEXITCODE=$null;& $tool.path @argv 2>&1|Tee-Object -FilePath $logPath -Append|Out-Host;$code=$LASTEXITCODE}catch{$failure=$_.Exception.Message}finally{Pop-Location;$ErrorActionPreference=$saved}
# First seal contains only prebound identities and actual typed exit, before all output hashing.
Save $callPath ([ordered]@{stage='upl_damp_component_run_r1.call';program=$tool;target_program=$h.program;arguments=$argv;target_arguments=$targetArgs;working_directory=$src;started_utc=$started;ended_utc=[DateTime]::UtcNow.ToString('o');direct_native_call=$true;typed_LASTEXITCODE_captured_immediately=($code -is [int]);owned_call_exited=($code -is [int]);exit_code=$code;invocation_failure=$failure;log_path=$logPath;memcheck_executed=$mem;direct_target_call=(!$mem);target_child_exit_separately_observed=$false;component_only=$true;solver_or_build_invoked=$false;physical_acceptance=$false})
$completion=$null;$done=$null;$files=@();$unchanged=$false;$zero=$false;$rateRows=0;$directRows=0;$summaryRows=0
try{
  Need ($code -is [int] -and $code -eq 0 -and !$failure) 'Owned component/tool failed; retain partials without retry'
  $text=[IO.File]::ReadAllText($logPath);$zero=(!$mem -or ($text -match 'ERROR SUMMARY: 0 errors' -and $text -match 'LEAK SUMMARY: 0 bytes leaked in 0 allocations'));Need $zero 'GPU Debug memory check rejected'
  $completion=E (Join-Path $folder 'completion.json');$done=J $completion.path
  Need ($done.passed -and $done.stage -ceq 'upl_damp_components_r1' -and $done.backend -ceq $backend -and $done.native_count -eq 1000 -and $done.fixed_count -eq 40 -and $done.direct_damping_cases -eq 5 -and $done.actual_force_calls -eq 3 -and $done.explicit_complete_rate_calls -eq 1 -and $done.conditional_reference_rows -eq 4000 -and $done.periodic_owner_checks -gt 0 -and $done.named_persistent_restores -eq 3 -and $done.changed_native_finished_Ace -gt 0) 'Declared component coverage rejected'
  Need ($done.eta0_actual_wrapper_noop -and $done.legacy_w_poison_dynamic_invariance -and $done.candidate_damping_enabled_before_Init -and $done.manufactured_component_only -and $done.reference_conditional_on_actual_C_and_wall_Ace -and $done.closed_normal_target_is_constructed_not_measured_face_flux -and !$done.Run_ComputeStep_or_SaveData_called -and $done.physical_steps_advanced -eq 0 -and !$done.eta0_or_defaultOFF_native_trajectory_verified -and $done.physical_acceptance -eq $false) 'Component limits/conditional wall target differ'
  if($gpu){Need $done.GPU_CTE_updates_use_production_ConstantDataUp 'Actual GPU constant refresh missing'}
  $power=[double]$done.actual_finished_damping_stage_power;Need (![double]::IsNaN($power) -and ![double]::IsInfinity($power) -and $power -lt 0) 'Measured damping power must be finite and negative'
  foreach($key in @('max_full_rate_over_original_budget','max_finished_increment_over_original_force_budget','max_load_target_over_original_force_budget')){$v=[double]$done.$key;Need (![double]::IsNaN($v) -and ![double]::IsInfinity($v) -and $v -ge 0 -and $v -le 1) ('Original component budget rejected: '+$key)}
  $rates=@(Import-Csv -LiteralPath (Join-Path $folder 'rates.csv'));$direct=@(Import-Csv -LiteralPath (Join-Path $folder 'damping.csv'));$summary=@(Import-Csv -LiteralPath (Join-Path $folder 'summary.csv'));$rateRows=$rates.Count;$directRows=$direct.Count;$summaryRows=$summary.Count
  Need ($rateRows -eq 4000 -and $directRows -eq $done.direct_rows -and $summaryRows -eq 6) 'Actual CSV/completion counts differ';$groups=@($direct|Group-Object -Property case);Need ($groups.Count -eq 5 -and @($groups|Where-Object{$_.Count -ne $directRows/5}).Count -eq 0 -and !(Compare-Object ($groups.Name|Sort-Object) @('0','1','2','3','4'))) 'Five complete direct CSV states required'
  foreach($r in $rates){$v=[double]$r.error_ratio;Need (![double]::IsNaN($v) -and ![double]::IsInfinity($v) -and $v -ge 0 -and $v -le 1) 'CSV original rate budget rejected'}
}catch{$failure=$_.Exception.Message}
try{V $bindings;$unchanged=$true}catch{if(!$failure){$failure=$_.Exception.Message}};if(Test-Path -LiteralPath $folder){$files=@(Get-ChildItem -LiteralPath $folder -File -Recurse|Sort-Object FullName|ForEach-Object{E $_.FullName})}
$passed=(!$failure -and $unchanged -and $zero -and $null -ne $done)
Save $record ([ordered]@{stage='upl_damp_component_run_r1';passed=[bool]$passed;configuration=$Configuration;backend=$backend;component_helper=$helperE;source_build=$buildE;program=$h.program;source_snapshot=$h.source_snapshot;documentation_snapshot=$h.documentation_snapshot;case_readme_snapshot=$h.case_readme_snapshot;canonical_programs_before=$h.canonical_programs_before;runtime=$h.runtime;prior_Debug_smoke_native=$prior;input_manifest=$manifestE;job=$job;call=(E $callPath);log=(E $logPath);completion=$completion;inputs=$bindings;files=$files;rates_csv_rows=$rateRows;direct_csv_rows=$directRows;summary_csv_rows=$summaryRows;source_inputs_objects_runtime_canonical_unchanged=$unchanged;memcheck_executed=$mem;memcheck_zero_errors_and_leaks=[bool]($mem -and $zero);target_child_exit_separately_observed=$false;conditional_wall_target_not_independent_flux=$true;manufactured_component_only=$true;solver_help_reader_or_build_invoked=$false;physical_acceptance=$false;failure=$failure})
if(!$passed){throw "Component rejected; preserve $record and all partials, no automatic retry"};Write-Output "One actual bounded component sealed: $record"
